public class DatasetUtilities_iterateDomainBounds_TriageGen2Test {

    /**
     * Test that a null dataset throws IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    /**
     * Test standard XYDataset where includeInterval is false.
     * Covers the 'else' block in the method.
     */
    @Test
    public void testIterateDomainBounds_StandardXYDataset_False() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);

        // Item 0: x=1.0
        when(dataset.getXValue(0, 0)).thenReturn(1.0);
        // Item 1: x=5.0
        when(dataset.getXValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    /**
     * Test standard XYDataset with NaN values.
     * Ensures NaN values are ignored.
     */
    @Test
    public void testIterateDomainBounds_StandardXYDataset_WithNaN() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);

        when(dataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getXValue(0, 1)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    /**
     * Test standard XYDataset with no valid data (all NaN).
     * Should return null because minimum > maximum (Infinity > -Infinity).
     */
    @Test
    public void testIterateDomainBounds_EmptyOrNaN_ReturnsNull() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);
        assertNull(result);
    }

    /**
     * Test IntervalXYDataset where includeInterval is true.
     * Covers the 'if (includeInterval && dataset instanceof IntervalXYDataset)' block.
     */
    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval() {
        IntervalXYDataset dataset = Mockito.mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);

        // XValue (center/point) = 10.0
        when(dataset.getXValue(0, 0)).thenReturn(10.0);
        // StartValue = 5.0
        when(dataset.getStartXValue(0, 0)).thenReturn(5.0);
        // EndValue = 15.0
        when(dataset.getEndXValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, true);

        // Bounds should cover [5.0, 15.0]
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    /**
     * Test IntervalXYDataset with NaNs in interval bounds.
     */
    @Test
    public void testIterateDomainBounds_IntervalXYDataset_WithNaN() {
        IntervalXYDataset dataset = Mockito.mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);

        when(dataset.getXValue(0, 0)).thenReturn(10.0);
        when(dataset.getStartXValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getEndXValue(0, 0)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, true);

        // Should ignore NaN start and use 10.0 and 20.0
        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    /**
     * Test includeInterval = true but dataset is NOT an IntervalXYDataset.
     * It should fall into the 'else' block (standard XYDataset logic).
     */
    @Test
    public void testIterateDomainBounds_IncludeIntervalTrue_ButNotIntervalDataset() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getXValue(0, 0)).thenReturn(2.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, true);

        assertEquals(2.0, result.getLower(), 1e-9);
        assertEquals(2.0, result.getUpper(), 1e-9);
    }
}
